# ==============================================================================# 029_SETTINGS_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS settings(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    category TEXT,    key_name TEXT,    value TEXT)""")conn.commit()SETTINGS = [("SYSTEM","NAME","IOTEC Mission Control"),("SYSTEM","VERSION","1.0.0"),("SYSTEM","LANGUAGE","pt-BR"),("SYSTEM","THEME","DARK"),("MAESTRO","STATUS","ONLINE"),("MAESTRO","AUTO_ANALYSIS","TRUE"),("API","PORT","5000"),("API","HOST","0.0.0.0"),("DATABASE","ENGINE","SQLITE"),("MISSION","DEFAULT_PRIORITY","NORMAL")]for category,key,value in SETTINGS:    cur.execute("""    SELECT id    FROM settings    WHERE category=?      AND key_name=?    """,(category,key))    if cur.fetchone() is None:        cur.execute("""        INSERT INTO settings(            created_at,            category,            key_name,            value        )        VALUES(?,?,?,?)        """,(            datetime.now().isoformat(),            category,            key,            value        ))conn.commit()cur.execute("""SELECTcategory,key_name,valueFROM settingsORDER BYcategory,key_name""")print("="*80)print("SETTINGS ENGINE")print("="*80)for row in cur.fetchall():    print(        f"{row['category']:<12}"        f"{row['key_name']:<20}"        f"{row['value']}"    )print("="*80)conn.close()

